-- Plantillas de notificaciones para el módulo de ofertas laborales y candidaturas
	 -- Oferta laboral - Notificación - Cierre vencido y estado no cerrado - Usuario asignado
	('d3c1d5b7-f8d2-4df4-9f6b-2c63aa6b8e41', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Oferta laboral con cierre vencido sin estado cerrada (usuario asignado)', 'Notificación al usuario asignado que la oferta ya ha caducado y no está cerrada.', 'Oferta laboral fuera de plazo:  $stic_job_offers_name', '$stic_job_offers_assigned_user_name:\r\n\r\nLa oferta laboral $stic_job_offers_name tiene la fecha de cierre de candidaturas vencida y actualmente está en estado $stic_job_offers_status.\r\n\r\nRevísela y, si procede, actualice su estado: $sugarurl/index.php?module=stic_Job_Offers&action=DetailView&record=$stic_job_offers_id', '<p>$stic_job_offers_assigned_user_name:</p>\n<p>La oferta laboral <strong>$stic_job_offers_name</strong> tiene la fecha de cierre de candidaturas vencida y actualmente está en estado <strong>$stic_job_offers_status</strong>.</p>\n<p><a href="$sugarurl/index.php?module=stic_Job_Offers&action=DetailView&record=$stic_job_offers_id">Revísela</a> y, si procede, actualice su estado.</p>', 0, '1', 0, 'notification'),
    -- Oferta laboral - Notificación - Cierre vencido y estado no cerrado - Interlocutor
    ('c2a9e9d1-1f5f-4c6c-9b3c-8d3c2a7f4b81', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Oferta laboral con cierre vencido sin estado cerrada (interlocutor)', 'Notificación al interlocutor que la oferta ya ha caducado y no está cerrada.', 'Oferta laboral fuera de plazo: $stic_job_offers_name', 'Apreciado/a $contact_name:\r\n\r\nLa oferta laboral $stic_job_offers_name tiene la fecha de cierre de candidaturas vencida y actualmente está en estado $stic_job_offers_status.\r\n\r\nRevísela y, si procede, actualice su estado: $portal_address/?internalpage=single_stic_job_offers&action=detail&id=$stic_job_offers_id', '<p>Apreciado/a $contact_name:</p>\n<p>La oferta laboral <strong>$stic_job_offers_name</strong> tiene la fecha de cierre de candidaturas vencida y actualmente está en estado <strong>$stic_job_offers_status</strong>.</p>\n<p><a href="$portal_address/?internalpage=single_stic_job_offers&action=detail&id=$stic_job_offers_id">Revísela</a> y, si procede, actualice su estado.</p>', 0, '1', 0, 'notification'),
    -- Candidatura Aceptada - Usuario asignado 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0001', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Candidatura aceptada (usuario asignado)', 'Notificación al usuario asignado cuando una candidatura pasa a Aceptada.', 'Candidatura aceptada: $stic_job_applications_stic_job_applications_stic_job_offers_name', '$stic_job_applications_assigned_user_name:\r\n\r\nLa candidatura de $stic_job_applications_stic_job_applications_contacts_name para la oferta $stic_job_applications_stic_job_applications_stic_job_offers_name ha sido aceptada.\r\n\r\nEnlace a la candidatura: $sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id', '<p>$stic_job_applications_assigned_user_name:</p><p>La candidatura de <strong>$stic_job_applications_stic_job_applications_contacts_name</strong> para la oferta <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong> ha sido <strong>aceptada</strong>.</p><p><a href="$sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id">Enlace a la candidatura</a>.</p>', 0, '1', 0, 'notification'),
    -- Candidatura Aceptada - Candidato 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0002', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Candidatura aceptada (candidato)', 'Notificación al candidato cuando una candidatura pasa a Aceptada.', 'Candidatura aceptada: $stic_job_applications_stic_job_applications_stic_job_offers_name', 'Apreciado/a $stic_job_applications_stic_job_applications_contacts_name:\r\n\r\nNos complace informarle que su candidatura para la oferta $stic_job_applications_stic_job_applications_stic_job_offers_name ha sido aceptada.\r\n\r\nEnlace a la candidatura: $portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id', '<p>Apreciado/a $stic_job_applications_stic_job_applications_contacts_name:</p><p>Nos complace informarle que su candidatura para la oferta <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong> ha sido <strong>aceptada</strong>.</p><p><a href="$portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id">Enlace a la candidatura</a>.</p>', 0, '1', 0, 'notification'),
    -- Candidatura Rechazada o cerrada - Usuario asignado 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0004', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Candidatura rechazada/cerrada (usuario asignado)', 'Notificación al usuario asignado cuando una candidatura pasa a Rechazada o cerrada.', 'Candidatura rechazada o cerrada: $stic_job_applications_stic_job_applications_stic_job_offers_name', '$stic_job_applications_assigned_user_name:\n\nLa candidatura de $stic_job_applications_stic_job_applications_contacts_name para la oferta $stic_job_applications_stic_job_applications_stic_job_offers_name ha sido rechazada.\r\n\r\nEnlace a la candidatura: $sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id', '<p>$stic_job_applications_assigned_user_name:</p><p>La candidatura de <strong>$stic_job_applications_stic_job_applications_contacts_name</strong> para la oferta <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong> ha sido rechazada.</p><p><a href=\"$sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id\">Enlace a la candidatura</a>.</p>', 0, '1', 0, 'notification'),
    -- Candidatura Rechazada o cerrada - Candidato 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0005', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Candidatura rechazada/cerrada (candidato)', 'Notificación al candidato cuando una candidatura pasa a Rechazada o cerrada.', 'Candidatura rechazada: $stic_job_applications_stic_job_applications_stic_job_offers_name', 'Apreciado/a $stic_job_applications_stic_job_applications_contacts_name:\n\nLe agradecemos el interés en la oferta de $stic_job_applications_stic_job_applications_stic_job_offers_name.\n\nLamentablemente, en esta ocasión se ha decidido continuar el proceso con otras candidaturas que se ajustan más a las características de la oferta.\r\n\r\nEnlace a la candidatura: $portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id', '<p>Apreciado/a $stic_job_applications_stic_job_applications_contacts_name:</p><p>Le agradecemos el interés en la oferta de <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong>.</p><p>Lamentablemente, en esta ocasión se ha decidido continuar el proceso con otras candidaturas que se ajustan más a las características de la oferta.</p><p><a href=\"$portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id\">Enlace a la candidatura</a>.</p><p>Le deseamos mucho éxito. Atentamente, $stic_job_offers_stic_job_offers_accounts_name</p>', 0, '1', 0, 'notification'),
    -- Candidatura Otros estados - Usuario asignado 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0007', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Candidatura otros estados (usuario asignado)', 'Notificación al usuario asignado cuando una candidatura pasa a Pendiente de entrevista o Entrevistada.', 'Candidatura $stic_job_applications_status: $stic_job_applications_stic_job_applications_stic_job_offers_name', '$stic_job_applications_assigned_user_name:\r\n\r\nLa candidatura de $stic_job_applications_stic_job_applications_contacts_name para la oferta $stic_job_applications_stic_job_applications_stic_job_offers_name ha cambiado a $stic_job_applications_status.\r\n\r\nEnlace a la candidatura: $sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id', '<p>$stic_job_applications_assigned_user_name,</p><p>La candidatura de <strong>$stic_job_applications_stic_job_applications_contacts_name</strong> para la oferta <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong> ha cambiado a <strong>$stic_job_applications_status</strong>.</p><p><a href="$sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id">Enlace a la candidatura</a>.</p>', 0, '1', 0, 'notification'),
    -- Candidatura Otros estados - Candidato 
    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0008', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Candidatura otros estados (candidato)', 'Notificación al candidato cuando una candidatura pasa a Pendiente de entrevista o Entrevistada.', 'Candidatura $stic_job_applications_status: $stic_job_applications_stic_job_applications_stic_job_offers_name', 'Apreciado/a $stic_job_applications_stic_job_applications_contacts_name:\r\n\r\nSu candidatura para la oferta $stic_job_applications_stic_job_applications_stic_job_offers_name ha cambiado a $stic_job_applications_status.\r\n\r\nEnlace a la candidatura: $portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id', '<p>Apreciado/a $stic_job_applications_stic_job_applications_contacts_name:</p><p>Su candidatura para la oferta <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong> ha cambiado a <strong>$stic_job_applications_status</strong>.</p><p><a href="$portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id">Enlace a la candidatura</a>.</p>', 0, '1', 0, 'notification'),
