    ('1a2d6f10-8e32-4f8a-9a11-3b1b7c2a0012', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Cambio de estado de oferta laboral (interlocutor)', 'Notificación al interlocutor del cambio de estado de una oferta.', 'Actualización de la oferta: $stic_job_offers_name', 'Apreciado/a $contact_name:\r\n\r\nLa oferta $stic_job_offers_name ha cambiado a $stic_job_offers_status.\r\n\r\nEnlace a la oferta: $portal_address/?internalpage=single_stic_job_offers&action=detail&id=$stic_job_offers_id', '<p>Apreciado/a $contact_name:</p><p>La oferta <strong>$stic_job_offers_name</strong> ha cambiado a <strong>$stic_job_offers_status</strong>.</p><p><a href="$portal_address/?internalpage=single_stic_job_offers&action=detail&id=$stic_job_offers_id">Enlace a la oferta</a>.</p>', 0, '1', 0, 'notification'),
