    ('6e6f5a91-2cb9-4f42-bf26-0a13b2f1c101', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Credenciales de acceso al área privada (persona)', 'Notificación de las credenciales de acceso al área privada cuando se activa el acceso de una persona.', 'Sus credenciales de acceso al área privada', '$contacts_name:\r\n\r\nYa tiene habilitado el acceso al área privada.\r\n\r\nUsuario: $contacts_stic_pa_username_c\r\nContraseña: $contacts_stic_pa_password_c\r\n\r\nPuede acceder en la dirección: $portal_address', '<p>$contacts_name:</p><p>Ya tiene habilitado el acceso al área privada.</p><p><strong>Usuario:</strong> $contacts_stic_pa_username_c<br><strong>Contraseña:</strong> $contacts_stic_pa_password_c</p><p>Puede acceder en la dirección: <a href="$portal_address">$portal_address</a></p>', 0, '1', 0, 'notification'),
    -- Área Privada - Credenciales de acceso - Organización
    ('6e6f5a91-2cb9-4f42-bf26-0a13b2f1c102', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Credenciales de acceso al área privada (organización)', 'Notificación de las credenciales de acceso al área privada cuando se activa el acceso de una organización.', 'Sus credenciales de acceso al área privada', '$accounts_name:\r\n\r\nYa tiene habilitado el acceso al área privada.\r\n\r\nUsuario: $accounts_stic_pa_username_c\r\nContraseña: $accounts_stic_pa_password_c\r\n\r\nPuede acceder en la dirección: $portal_address\r\n\r\n', '<p>$accounts_name:</p><p>Ya tiene habilitado el acceso al área privada.</p><p><strong>Usuario:</strong> $accounts_stic_pa_username_c<br><strong>Contraseña:</strong> $accounts_stic_pa_password_c</p><p>Puede acceder en la dirección: <a href="$portal_address">$portal_address</a></p>', 0, '1', 0, 'notification'),
