    ('7a9f8f3a-2d1f-4a40-9dd6-7c6f9e1b7001', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Candidatura creada (usuario asignado)', 'Notificación al usuario asignado cuando se crea una nueva candidatura.', 'Nueva candidatura recibida: $stic_job_applications_stic_job_applications_stic_job_offers_name', '$stic_job_applications_assigned_user_name:\r\n\r\n$stic_job_applications_stic_job_applications_contacts_name ha presentado su candidatura a la oferta $stic_job_applications_stic_job_applications_stic_job_offers_name.\r\n\r\nEnlace a la candidatura: $sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id', '<p>$stic_job_applications_assigned_user_name:</p><p><strong>$stic_job_applications_stic_job_applications_contacts_name</strong> ha presentado su candidatura a la oferta <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong>.</p><p><a href=\"$sugarurl/index.php?module=stic_Job_Applications&action=DetailView&record=$stic_job_applications_id\">Enlace a la candidatura</a>.</p>', 0, '1', 0, 'notification'),
    -- Candidatura - Notificación - Candidatura registrada (candidato)
    ('7a9f8f3a-2d1f-4a40-9dd6-7c6f9e1b7003', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Candidatura creada (candidato)', 'Notificación al candidato que su candidatura ha sido registrada.', 'Candidatura recibida: $stic_job_applications_stic_job_applications_stic_job_offers_name', 'Apreciado/a $stic_job_applications_stic_job_applications_contacts_name:\r\n\r\nHemos recibido su candidatura para la oferta $stic_job_applications_stic_job_applications_stic_job_offers_name.\r\n\r\nEnlace a la candidatura: $portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id', '<p>Apreciado/a $stic_job_applications_stic_job_applications_contacts_name:</p><p>Hemos recibido su candidatura para la oferta <strong>$stic_job_applications_stic_job_applications_stic_job_offers_name</strong>.</p><p><a href=\"$portal_address/?internalpage=single_stic_job_applications&action=detail&id=$stic_job_applications_id\">Enlace a la candidatura</a>.</p>', 0, '1', 0, 'notification'),
    -- Mensaje - Notificación - Nuevo mensaje en conversación
    ('7a9f8f3a-2d1f-4a40-9dd6-7c6f9e1b7002', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Nuevo mensaje en conversación (usuario asignado)', 'Notificación al usuario asignado cuando un usuario del área privada emite un mensaje en una conversación.', 'Nuevo mensaje recibido', '$stic_messages_assigned_user_name:\r\n\r\nHa recibido un mensaje de una conversación del área privada.\r\n\r\nConversación:\r\n$stic_conversations_subject\r\n\r\nMensaje:\r\n$stic_messages_message\r\n\r\nEnlace al mensaje: $sugarurl/index.php?module=stic_Messages&action=DetailView&record=$stic_messages_id', '<p>$stic_messages_assigned_user_name:</p><p>Ha recibido un mensaje de una conversación del área privada.</p><p><strong>Conversación:</strong><br>$stic_conversations_subject</p><p><strong>Mensaje:</strong><br>$stic_messages_message</p><p><a href=\"$sugarurl/index.php?module=stic_Messages&action=DetailView&record=$stic_messages_id\">Enlace al mensaje</a>.</p>', 0, '1', 0, 'notification'),
    -- Ofertas laborales - Notificación - Nueva oferta laboral (usuario asignado)
    ('3c0a5f6e-1111-4f8a-9a11-3b1b7c2a0101', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Nueva oferta laboral (usuario asignado)', 'Notificación al usuario asignado de la creación de una oferta laboral.', 'Oferta creada: $stic_job_offers_name', '$stic_job_offers_assigned_user_name:\r\n\r\nSe ha creado una nueva oferta laboral: $stic_job_offers_name.\r\n\r\nEnlace a la oferta: $sugarurl/index.php?module=stic_Job_Offers&action=DetailView&record=$stic_job_offers_id', '<p>$stic_job_offers_assigned_user_name:</p><p>Se ha creado una nueva oferta laboral: <strong>$stic_job_offers_name</strong>.</p><p><a href="$sugarurl/index.php?module=stic_Job_Offers&action=DetailView&record=$stic_job_offers_id">Enlace a la oferta</a>.</p>', 0, '1', 0, 'notification'),
    -- Mensaje - Notificación - Nuevo mensaje en conversación (persona relacionada)
    ('7a9f8f3a-2d1f-4a40-9dd6-7c6f9e1b7004', NOW(), NOW(), '1', '1', NULL, 'Ejemplo - Nuevo mensaje en conversación (usuario del área privada)', 'Notificación al usuario del área privada cuando el usuario asignado emite un mensaje en una conversación.', 'Nuevo mensaje recibido', 'Apreciado/a $contact_name:\r\n\r\nHa recibido un mensaje en el área privada.\r\n\r\nConversación:\r\n$stic_conversations_subject\r\n\r\nMensaje:\r\n$stic_messages_message\r\n\r\nLo puede consultar y responder en el área privada: $portal_address/?internalpage=single_stic_chat&action=detail&id=$stic_conversations_id', '<p>Apreciado/a $contact_name:</p><p>Ha recibido un mensaje en el área privada.</p><p><strong>Conversación:</strong><br>$stic_conversations_subject</p><p><strong>Mensaje:</strong><br>$stic_messages_message</p><p>Lo puede consultar y responder en el área privada: <a href="$portal_address/?internalpage=single_stic_chat&action=detail&id=$stic_conversations_id">$portal_address</a>.</p>', 0, '1', 0, 'notification'),
